from collections import defaultdict


def transform(grid):
    h, w = len(grid), len(grid[0])
    candidates = []
    for kind in ('row', 'col', 'sum', 'diff'):
        lines = defaultdict(list)
        for r in range(h):
            for c in range(w):
                v = grid[r][c]
                if v:
                    k = r if kind == 'row' else c if kind == 'col' else r + c if kind == 'sum' else c - r
                    lines[k].append(v)
        labels = {k: vs[0] for k, vs in lines.items() if len(set(vs)) == 1}
        score = sum(len(lines[k]) ** 2 for k in labels)
        candidates.append((score, kind, labels))

    _, kind, labels = max(candidates, key=lambda x: x[0])
    if not labels:
        return [row[:] for row in grid]

    # Select the shortest periodic stripe sequence consistent with all clues.
    period = None
    phases = None
    for p in range(max(1, len(labels)), 2 * max(h, w) + 1):
        trial = {}
        for k, color in labels.items():
            phase = k % p
            if phase in trial and trial[phase] != color:
                break
            trial[phase] = color
        else:
            period, phases = p, trial
            break
    if period is None:
        raise ValueError('inconsistent stripe clues')

    # Fill unconstrained cycle phases from the nearest known phase, preferring
    # the next known phase when distances tie.
    known = dict(phases)
    for phase in range(period):
        if phase in known:
            continue
        for distance in range(1, period + 1):
            following = (phase + distance) % period
            preceding = (phase - distance) % period
            if following in known:
                phases[phase] = known[following]
                break
            if preceding in known:
                phases[phase] = known[preceding]
                break

    def value(r, c):
        k = r if kind == 'row' else c if kind == 'col' else r + c if kind == 'sum' else c - r
        return phases.get(k % period, 0)

    return [[value(r, c) for c in range(w)] for r in range(h)]

